LOCK TABLE public.users, public.events, public.event_participants, public.event_payment_attempts, public.telegram_contacts, public.telegram_broadcasts, public.telegram_broadcast_deliveries IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE menorah_media_preservation ON COMMIT DROP AS SELECT (SELECT jsonb_object_agg(name,value) FROM (SELECT 'users' name, jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) value FROM public.users t UNION ALL SELECT 'events' name, jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) value FROM public.events t UNION ALL SELECT 'event_participants' name, jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) value FROM public.event_participants t UNION ALL SELECT 'event_payment_attempts' name, jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) value FROM public.event_payment_attempts t UNION ALL SELECT 'telegram_contacts' name, jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) value FROM public.telegram_contacts t UNION ALL SELECT 'telegram_broadcasts' name, jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg((to_jsonb(t)-'image_url')::text,'' ORDER BY id),''))) value FROM public.telegram_broadcasts t UNION ALL SELECT 'telegram_broadcast_deliveries' name, jsonb_build_object('count',count(*),'hash',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) value FROM public.telegram_broadcast_deliveries t) f) fingerprints, (SELECT jsonb_build_object('rls',relrowsecurity,'acl',relacl::text,'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY policyname),'[]'::jsonb) FROM pg_policies p WHERE schemaname='public' AND tablename='telegram_broadcasts')) FROM pg_class WHERE oid='public.telegram_broadcasts'::regclass) protections;
